css:
@font-face {
  font-family: "THSarabun";
  src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page { size: A4 portrait; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial, sans-serif;
  font-size: 9pt;
  color: #111;
}

.print-format { padding: 0 !important; margin: 0 !important; min-height: unset !important; max-width: unset !important; }
.print-format-preview { padding: 0 !important; }
.page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;
  page-break-after: always;
  background-size: 210mm 297mm;
  background-repeat: no-repeat;
  font-family: "THSarabun", "Sarabun", Arial, sans-serif;
  font-size: 11pt;
  color: #111;
}
.page:last-child { page-break-after: auto; }
.f { position: absolute; line-height: 1.08; white-space: normal; }

.field { position: absolute; line-height: 1.08; white-space: nowrap; }
.text-right { text-align: right; }
.amount { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.tr { text-align: right; }
.tc { text-align: center; }
.nowrap { white-space: nowrap; overflow: hidden; }
.small { font-size: 9.5pt; }
table { width: 100%; border-collapse: collapse; table-layout: fixed; }
td { padding: 0.8mm 1mm; vertical-align: top; line-height: 1.05; word-break: break-word; }

.page { background-image: url("/assets/connect_diagnostics_core/images/print_formats/ex_re6904047_1.webp?v=1779960652"); }

/* Header boxes - aligned to EX RE6904047 form */
.company-tax { top: 38mm; left: 82mm; width: 45mm; text-align: left; font-size: 10.5pt; }
.customer-name { top: 58mm; left: 31mm; width: 78mm; }
.customer-address { top: 72mm; left: 31mm; width: 78mm; line-height: 1.12; }
.customer-tax { top: 85.5mm; left: 50mm; width: 62mm; }
.receipt-no { top: 57.5mm; left: 144mm; width: 42mm; }
.receipt-date { top: 64.5mm; left: 137mm; width: 49mm; }
.salesman { top: 91mm; left: 145mm; width: 41mm; }

/* Reference table */
.refs { top: 116mm; left: 14mm; width: 192mm; font-size: 10pt; }
.refs table { table-layout: fixed; border-collapse: collapse; }
.refs td { padding: 1.1mm 1.2mm; line-height: 1.05; height: 7mm; }
.col-no { width: 10mm; text-align: center; }
.col-inv { width: 38mm; }
.col-date { width: 25mm; text-align: center; }
.col-due { width: 25mm; text-align: center; }
.col-amount { width: 31mm; text-align: right; }
.amount-first { display: inline-block; transform: translateX(-9mm); }
.amount-outstanding { display: inline-block; transform: translateX(-9mm); }
.amount-paid { display: inline-block; transform: translateX(-9mm); }
.col-outstanding { width: 31mm; text-align: right; }
.col-paid { width: 32mm; text-align: right; }
.total-paid { top: 228.8mm; left: 176mm; width: 26mm; font-weight: 700; }

/* Payment section */
.mode-cash { display: none; }
.mode-cheque { display: none; }
.reference-no { top: 243.7mm; left: 99mm; width: 30mm; text-align: left; }
.reference-date { top: 256.7mm; left: 114mm; width: 25mm; text-align: center; font-size: 10.5pt; }
.reference-amount { top: 262.4mm; left: 64mm; width: 54mm; text-align: right; font-size: 10.5pt; }


/* Optional mm ruler: show only with debug_ruler=1 in printview URL */
.debug-ruler {
  position: absolute;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  background-image:
    linear-gradient(to right, rgba(255, 0, 0, 0.22) 0.15mm, transparent 0.15mm),
    linear-gradient(to bottom, rgba(255, 0, 0, 0.22) 0.15mm, transparent 0.15mm),
    linear-gradient(to right, rgba(0, 0, 255, 0.35) 0.2mm, transparent 0.2mm),
    linear-gradient(to bottom, rgba(0, 0, 255, 0.35) 0.2mm, transparent 0.2mm);
  background-size: 1mm 1mm, 1mm 1mm, 10mm 10mm, 10mm 10mm;
}
.debug-ruler::before {
  content: "mm ruler: red=1mm blue=10mm";
  position: absolute;
  top: 2mm;
  left: 2mm;
  padding: 1mm 2mm;
  background: rgba(255,255,255,0.9);
  color: #c00;
  font-size: 8pt;
}
.debug-payment-box {
  position: absolute;
  left: 70mm;
  top: 248mm;
  width: 75mm;
  height: 32mm;
  border: 0.4mm dashed #f00;
  z-index: 10000;
  pointer-events: none;
}
